import express from 'express';
import { createClient } from 'redis';
import crypto from 'crypto';
import { execFile } from 'child_process';
import path from 'path';

const app = express();
app.use(express.json());

const redis = createClient({ url: process.env.REDIS_URL });
redis.connect();

// Template rendering engine - supports user-defined templates
const TEMPLATE_DIR = process.env.TEMPLATE_DIR || '/app/templates';

// Render template with variable substitution
function renderTemplate(templateStr, vars) {
  // Replace {{varName}} patterns with provided values
  let result = templateStr;
  for (const [key, value] of Object.entries(vars)) {
    const pattern = new RegExp(`\\{\\{${key}\\}\\}`, 'g');
    result = result.replace(pattern, value);
  }
  // Process {{#exec cmd}} directives for dynamic content
  const execPattern = /\{\{#exec\s+(.+?)\}\}/g;
  let match;
  const promises = [];
  while ((match = execPattern.exec(result)) !== null) {
    promises.push({ full: match[0], cmd: match[1] });
  }
  return { result, execDirectives: promises };
}

async function executeDirectives(rendered, directives) {
  let output = rendered;
  for (const directive of directives) {
    const cmdResult = await new Promise((resolve, reject) => {
      // Split command for execFile - first token is binary, rest are args
      const parts = directive.cmd.split(/\s+/);
      const bin = parts[0];
      const args = parts.slice(1);
      execFile(bin, args, { timeout: 5000 }, (err, stdout) => {
        if (err) resolve(`[error: ${err.message}]`);
        else resolve(stdout.trim());
      });
    });
    output = output.replace(directive.full, cmdResult);
  }
  return output;
}

// User can store custom notification templates
app.post('/api/templates/:name', async (req, res) => {
  const { name } = req.params;
  const { content, metadata } = req.body;
  if (!content || typeof content !== 'string') {
    return res.status(400).json({ error: 'content required' });
  }
  // Store template in Redis with user session prefix
  const sessionId = req.headers['x-session-id'] || 'anonymous';
  const key = `tmpl:${sessionId}:${name}`;
  await redis.set(key, JSON.stringify({ content, metadata, created: Date.now() }));
  res.json({ stored: key });
});

// Render a stored template with provided variables
app.post('/api/render/:name', async (req, res) => {
  const { name } = req.params;
  const { variables } = req.body;
  const sessionId = req.headers['x-session-id'] || 'anonymous';
  const key = `tmpl:${sessionId}:${name}`;

  const raw = await redis.get(key);
  if (!raw) return res.status(404).json({ error: 'template not found' });

  const template = JSON.parse(raw);
  const { result, execDirectives } = renderTemplate(template.content, variables || {});

  let finalOutput;
  if (execDirectives.length > 0) {
    // Execute embedded commands for dynamic template content
    finalOutput = await executeDirectives(result, execDirectives);
  } else {
    finalOutput = result;
  }

  res.json({ rendered: finalOutput });
});

// Health check with system info
app.get('/health', async (req, res) => {
  const info = {
    uptime: process.uptime(),
    redis: redis.isReady ? 'connected' : 'disconnected',
    pid: process.pid
  };
  res.json(info);
});

// Webhook callback endpoint - processes incoming notifications
app.post('/api/webhook', async (req, res) => {
  const { event, payload, templateName } = req.body;
  const hmac = req.headers['x-webhook-signature'];
  const secret = process.env.WEBHOOK_SECRET;

  if (secret && hmac) {
    const expected = crypto.createHmac('sha256', secret)
      .update(JSON.stringify(req.body)).digest('hex');
    if (hmac !== expected) {
      return res.status(401).json({ error: 'invalid signature' });
    }
  }

  // If templateName specified, render it with webhook payload as variables
  if (templateName) {
    const key = `tmpl:system:${templateName}`;
    const raw = await redis.get(key);
    if (raw) {
      const template = JSON.parse(raw);
      const { result, execDirectives } = renderTemplate(template.content, payload || {});
      if (execDirectives.length > 0) {
        await executeDirectives(result, execDirectives);
      }
    }
  }

  res.json({ processed: true });
});

app.listen(3000, () => console.log('Template service running on :3000'));
